{-| @Pudu.Backend.Runtime.Host.TlsTrust — system trust callbacks for the
    OpenSSL transport on iOS and Android. -}
module Pudu.Backend.Runtime.Host.TlsTrust (appleTrust, androidTrust) where

import Data.Text (Text)

{-| Apple evaluates the received chain against the system trust store.
    OpenSSL still holds the socket, TLS state, and configured peer identity. -}
appleTrust :: [Text]
appleTrust =
  [ "#if defined(PUDU_TLS_APPLE_TRUST)"
  , "#include <CoreFoundation/CoreFoundation.h>"
  , "#include <Security/Security.h>"
  , "#include <openssl/x509v3.h>"
  , "static int pudu_host_tls_apple_verify(X509_STORE_CTX *store, void *unused) {"
  , "  X509 *peer = X509_STORE_CTX_get0_cert(store);"
  , "  STACK_OF(X509) *chain = X509_STORE_CTX_get0_untrusted(store);"
  , "  X509_VERIFY_PARAM *identity = X509_STORE_CTX_get0_param(store);"
  , "  const char *dns = X509_VERIFY_PARAM_get0_host(identity, 0);"
  , "  char *ip = NULL;"
  , "  CFStringRef host = NULL;"
  , "  CFMutableArrayRef certificates = NULL;"
  , "  SecPolicyRef policy = NULL;"
  , "  SecTrustRef trust = NULL;"
  , "  int error = X509_V_ERR_CERT_REJECTED;"
  , "  (void)unused;"
  , "  if (peer == NULL) goto done;"
  , "  if (dns != NULL) {"
  , "    if (X509_check_host(peer, dns, 0, 0, NULL) != 1) { error = X509_V_ERR_HOSTNAME_MISMATCH; goto done; }"
  , "    host = CFStringCreateWithCString(NULL, dns, kCFStringEncodingUTF8);"
  , "    if (host == NULL) goto done;"
  , "  } else {"
  , "    ip = X509_VERIFY_PARAM_get1_ip_asc(identity);"
  , "    if (ip == NULL || X509_check_ip_asc(peer, ip, 0) != 1) { error = X509_V_ERR_IP_ADDRESS_MISMATCH; goto done; }"
  , "  }"
  , "  certificates = CFArrayCreateMutable(NULL, 0, &kCFTypeArrayCallBacks);"
  , "  if (certificates == NULL) goto done;"
  , "  for (int index = -1, count = chain != NULL ? sk_X509_num(chain) : 0; index < count; ++index) {"
  , "    X509 *item = index < 0 ? peer : sk_X509_value(chain, index);"
  , "    if (index >= 0 && X509_cmp(item, peer) == 0) continue;"
  , "    unsigned char *der = NULL;"
  , "    int length = i2d_X509(item, &der);"
  , "    CFDataRef bytes = length > 0 ? CFDataCreate(NULL, der, length) : NULL;"
  , "    OPENSSL_free(der);"
  , "    if (bytes == NULL) goto done;"
  , "    SecCertificateRef certificate = SecCertificateCreateWithData(NULL, bytes);"
  , "    CFRelease(bytes);"
  , "    if (certificate == NULL) goto done;"
  , "    CFArrayAppendValue(certificates, certificate);"
  , "    CFRelease(certificate);"
  , "  }"
  , "  policy = SecPolicyCreateSSL(true, host);"
  , "  if (policy == NULL || SecTrustCreateWithCertificates(certificates, policy, &trust) != errSecSuccess"
  , "      || trust == NULL || SecTrustSetNetworkFetchAllowed(trust, false) != errSecSuccess) goto done;"
  , "  if (SecTrustEvaluateWithError(trust, NULL)) error = X509_V_OK;"
  , "done:"
  , "  if (trust != NULL) CFRelease(trust);"
  , "  if (policy != NULL) CFRelease(policy);"
  , "  if (certificates != NULL) CFRelease(certificates);"
  , "  if (host != NULL) CFRelease(host);"
  , "  OPENSSL_free(ip);"
  , "  X509_STORE_CTX_set_error(store, error);"
  , "  return error == X509_V_OK;"
  , "}"
  , "#endif"
  ]

{-| Android hosts supply their process VM before entering the embedded program.
    Each verification acquires a thread-local JNI environment and releases it
    only when this call had to attach the thread. -}
androidTrust :: [Text]
androidTrust =
  [ "#if defined(PUDU_TLS_ANDROID_TRUST)"
  , "#include <jni.h>"
  , "#include <stdatomic.h>"
  , "#include <openssl/x509v3.h>"
  , "static _Atomic(JavaVM *) pudu_host_tls_vm = NULL;"
  , "int pudu_program_android_enable_tls(void *vm);"
  , "int pudu_program_android_enable_tls(void *vm) {"
  , "  JavaVM *prior = NULL;"
  , "  if (vm == NULL) return 0;"
  , "  return atomic_compare_exchange_strong(&pudu_host_tls_vm, &prior, (JavaVM *)vm) || prior == vm;"
  , "}"
  , "#define PUDU_JNI_GET(into, value) do { (into) = (value); if ((into) == NULL || (*env)->ExceptionCheck(env)) goto done; } while (0)"
  , "static int pudu_host_tls_android_chain(JNIEnv *env, X509 *peer, STACK_OF(X509) *chain, const char *auth, const char *name) {"
  , "  int verified = 0;"
  , "  int count = chain != NULL ? sk_X509_num(chain) : 0, used = 1;"
  , "  jclass tm_factory, x509_manager, extensions, certificate, cert_factory, stream_type;"
  , "  jmethodID default_algorithm, get_manager, init_manager, get_managers, new_extensions, check;"
  , "  jmethodID get_factory, decode, new_stream;"
  , "  jobject factory, manager = NULL, verifier, decoder, result;"
  , "  jobjectArray managers, certificates;"
  , "  jstring default_name, kind, host, auth_type;"
  , "  if ((*env)->PushLocalFrame(env, 32) != 0) { (*env)->ExceptionClear(env); return 0; }"
  , "  PUDU_JNI_GET(tm_factory, (*env)->FindClass(env, \"javax/net/ssl/TrustManagerFactory\"));"
  , "  PUDU_JNI_GET(x509_manager, (*env)->FindClass(env, \"javax/net/ssl/X509TrustManager\"));"
  , "  PUDU_JNI_GET(extensions, (*env)->FindClass(env, \"android/net/http/X509TrustManagerExtensions\"));"
  , "  PUDU_JNI_GET(certificate, (*env)->FindClass(env, \"java/security/cert/X509Certificate\"));"
  , "  PUDU_JNI_GET(cert_factory, (*env)->FindClass(env, \"java/security/cert/CertificateFactory\"));"
  , "  PUDU_JNI_GET(stream_type, (*env)->FindClass(env, \"java/io/ByteArrayInputStream\"));"
  , "  PUDU_JNI_GET(default_algorithm, (*env)->GetStaticMethodID(env, tm_factory, \"getDefaultAlgorithm\", \"()Ljava/lang/String;\"));"
  , "  PUDU_JNI_GET(get_manager, (*env)->GetStaticMethodID(env, tm_factory, \"getInstance\", \"(Ljava/lang/String;)Ljavax/net/ssl/TrustManagerFactory;\"));"
  , "  PUDU_JNI_GET(init_manager, (*env)->GetMethodID(env, tm_factory, \"init\", \"(Ljava/security/KeyStore;)V\"));"
  , "  PUDU_JNI_GET(get_managers, (*env)->GetMethodID(env, tm_factory, \"getTrustManagers\", \"()[Ljavax/net/ssl/TrustManager;\"));"
  , "  PUDU_JNI_GET(new_extensions, (*env)->GetMethodID(env, extensions, \"<init>\", \"(Ljavax/net/ssl/X509TrustManager;)V\"));"
  , "  PUDU_JNI_GET(check, (*env)->GetMethodID(env, extensions, \"checkServerTrusted\", \"([Ljava/security/cert/X509Certificate;Ljava/lang/String;Ljava/lang/String;)Ljava/util/List;\"));"
  , "  PUDU_JNI_GET(get_factory, (*env)->GetStaticMethodID(env, cert_factory, \"getInstance\", \"(Ljava/lang/String;)Ljava/security/cert/CertificateFactory;\"));"
  , "  PUDU_JNI_GET(decode, (*env)->GetMethodID(env, cert_factory, \"generateCertificate\", \"(Ljava/io/InputStream;)Ljava/security/cert/Certificate;\"));"
  , "  PUDU_JNI_GET(new_stream, (*env)->GetMethodID(env, stream_type, \"<init>\", \"([B)V\"));"
  , "  PUDU_JNI_GET(default_name, (*env)->CallStaticObjectMethod(env, tm_factory, default_algorithm));"
  , "  PUDU_JNI_GET(factory, (*env)->CallStaticObjectMethod(env, tm_factory, get_manager, default_name));"
  , "  (*env)->CallVoidMethod(env, factory, init_manager, (jobject)NULL);"
  , "  if ((*env)->ExceptionCheck(env)) goto done;"
  , "  PUDU_JNI_GET(managers, (*env)->CallObjectMethod(env, factory, get_managers));"
  , "  for (jsize i = 0, length = (*env)->GetArrayLength(env, managers); i < length; ++i) {"
  , "    PUDU_JNI_GET(manager, (*env)->GetObjectArrayElement(env, managers, i));"
  , "    if ((*env)->IsInstanceOf(env, manager, x509_manager)) break;"
  , "    (*env)->DeleteLocalRef(env, manager);"
  , "    manager = NULL;"
  , "  }"
  , "  if (manager == NULL) goto done;"
  , "  PUDU_JNI_GET(verifier, (*env)->NewObject(env, extensions, new_extensions, manager));"
  , "  PUDU_JNI_GET(kind, (*env)->NewStringUTF(env, \"X.509\"));"
  , "  PUDU_JNI_GET(decoder, (*env)->CallStaticObjectMethod(env, cert_factory, get_factory, kind));"
  , "  for (int i = 0; i < count; ++i) if (X509_cmp(sk_X509_value(chain, i), peer) != 0) ++used;"
  , "  PUDU_JNI_GET(certificates, (*env)->NewObjectArray(env, used, certificate, NULL));"
  , "  for (int i = -1, written = 0; i < count; ++i) {"
  , "    X509 *item = i < 0 ? peer : sk_X509_value(chain, i);"
  , "    if (i >= 0 && X509_cmp(item, peer) == 0) continue;"
  , "    unsigned char *der = NULL;"
  , "    int length = i2d_X509(item, &der);"
  , "    jbyteArray bytes = length > 0 ? (*env)->NewByteArray(env, length) : NULL;"
  , "    if (bytes != NULL && !(*env)->ExceptionCheck(env)) (*env)->SetByteArrayRegion(env, bytes, 0, length, (const jbyte *)der);"
  , "    OPENSSL_free(der);"
  , "    if (bytes == NULL || (*env)->ExceptionCheck(env)) goto done;"
  , "    jobject stream, decoded;"
  , "    PUDU_JNI_GET(stream, (*env)->NewObject(env, stream_type, new_stream, bytes));"
  , "    PUDU_JNI_GET(decoded, (*env)->CallObjectMethod(env, decoder, decode, stream));"
  , "    (*env)->SetObjectArrayElement(env, certificates, written++, decoded);"
  , "    if ((*env)->ExceptionCheck(env)) goto done;"
  , "    (*env)->DeleteLocalRef(env, decoded);"
  , "    (*env)->DeleteLocalRef(env, stream);"
  , "    (*env)->DeleteLocalRef(env, bytes);"
  , "  }"
  , "  PUDU_JNI_GET(host, (*env)->NewStringUTF(env, name));"
  , "  PUDU_JNI_GET(auth_type, (*env)->NewStringUTF(env, auth));"
  , "  PUDU_JNI_GET(result, (*env)->CallObjectMethod(env, verifier, check, certificates, auth_type, host));"
  , "  verified = 1;"
  , "done:"
  , "  if ((*env)->ExceptionCheck(env)) (*env)->ExceptionClear(env);"
  , "  (void)(*env)->PopLocalFrame(env, NULL);"
  , "  return verified;"
  , "}"
  , "#undef PUDU_JNI_GET"
  , "static const char *pudu_host_tls_android_auth(X509_STORE_CTX *store) {"
  , "  SSL *session = X509_STORE_CTX_get_ex_data(store, SSL_get_ex_data_X509_STORE_CTX_idx());"
  , "  const SSL_CIPHER *cipher = session != NULL ? SSL_get_pending_cipher(session) : NULL;"
  , "  if (session != NULL && SSL_version(session) == TLS1_3_VERSION) return \"GENERIC\";"
  , "  if (cipher == NULL) return \"UNKNOWN\";"
  , "  switch (SSL_CIPHER_get_kx_nid(cipher)) {"
  , "    case NID_kx_rsa: return \"RSA\";"
  , "    case NID_kx_dhe: return SSL_CIPHER_get_auth_nid(cipher) == NID_auth_dss ? \"DHE_DSS\" : \"DHE_RSA\";"
  , "    case NID_kx_ecdhe: return SSL_CIPHER_get_auth_nid(cipher) == NID_auth_ecdsa ? \"ECDHE_ECDSA\" : \"ECDHE_RSA\";"
  , "    default: return \"UNKNOWN\";"
  , "  }"
  , "}"
  , "static int pudu_host_tls_android_verify(X509_STORE_CTX *store, void *unused) {"
  , "  JavaVM *vm = atomic_load(&pudu_host_tls_vm);"
  , "  X509 *peer = X509_STORE_CTX_get0_cert(store);"
  , "  X509_VERIFY_PARAM *identity = X509_STORE_CTX_get0_param(store);"
  , "  const char *dns = X509_VERIFY_PARAM_get0_host(identity, 0);"
  , "  char *ip = NULL;"
  , "  JNIEnv *env = NULL;"
  , "  int attached = 0, error = X509_V_ERR_CERT_REJECTED;"
  , "  (void)unused;"
  , "  if (peer == NULL || vm == NULL) goto done;"
  , "  if (dns != NULL) {"
  , "    if (X509_check_host(peer, dns, 0, 0, NULL) != 1) { error = X509_V_ERR_HOSTNAME_MISMATCH; goto done; }"
  , "  } else {"
  , "    ip = X509_VERIFY_PARAM_get1_ip_asc(identity);"
  , "    if (ip == NULL || X509_check_ip_asc(peer, ip, 0) != 1) { error = X509_V_ERR_IP_ADDRESS_MISMATCH; goto done; }"
  , "  }"
  , "  jint state = (*vm)->GetEnv(vm, (void **)&env, JNI_VERSION_1_6);"
  , "  if (state == JNI_EDETACHED) {"
  , "    if ((*vm)->AttachCurrentThread(vm, &env, NULL) != JNI_OK) goto done;"
  , "    attached = 1;"
  , "  } else if (state != JNI_OK) goto done;"
  , "  if ((*env)->ExceptionCheck(env)) goto done;"
  , "  for (const unsigned char *letter = (const unsigned char *)(dns != NULL ? dns : ip); *letter; ++letter)"
  , "    if (*letter > 127) { error = X509_V_ERR_HOSTNAME_MISMATCH; goto done; }"
  , "  if (pudu_host_tls_android_chain(env, peer, X509_STORE_CTX_get0_untrusted(store), pudu_host_tls_android_auth(store), dns != NULL ? dns : ip)) error = X509_V_OK;"
  , "done:"
  , "  if (attached) (void)(*vm)->DetachCurrentThread(vm);"
  , "  OPENSSL_free(ip);"
  , "  X509_STORE_CTX_set_error(store, error);"
  , "  return error == X509_V_OK;"
  , "}"
  , "#endif"
  ]
